<?phpsession_start();// Database connection$host = 'localhost';$dbname = 'moviedb';$username = 'root';$password = '';$port = 3307;$conn = new mysqli($host, $username, $password, $dbname, $port);if ($conn->connect_error) {    die("Connection failed: " . $conn->connect_error);}$error = "";if ($_SERVER["REQUEST_METHOD"] === "POST") {    $user = trim($_POST["username"]);    $birthdate = $_POST["birthdate"];    if (empty($user) || empty($birthdate)) {        $error = "Please enter both username and date of birth.";    } else {        $sql = "SELECT * FROM users WHERE username = ?";        $stmt = $conn->prepare($sql);        $stmt->bind_param("s", $user);        $stmt->execute();        $result = $stmt->get_result();        if ($result && $result->num_rows === 1) {            $row = $result->fetch_assoc();            if ($row['birthdate'] === $birthdate) {                // Save username and security answer hash in session                $_SESSION['pending_username'] = $user;                $_SESSION['security_answer_hash'] = $row['security_answer_hash'];                $_SESSION['security_question'] = $row['security_question'];                // Redirect to security question page                header("Location: security_question.php");                exit;            } else {                $error = "Date of birth does not match.";            }        } else {            $error = "Username not found.";        }    }}?><!DOCTYPE html><html lang="en"><head>  <meta charset="UTF-8" />  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>  <title>Recover Account - Movielist</title>  <link rel="stylesheet" href="css/login.css?v=2">  <style>    .error {      color: red;      text-align: center;      font-weight: bold;    }  </style></head><body class="dark-theme">  <div class="login-container">    <form class="login-box" method="POST" action="forgot_password.php">      <h2>Recover Profile Access</h2>      <?php if (!empty($error)): ?>        <div class="error"><?php echo $error; ?></div>      <?php endif; ?>      <label>Username</label>      <input type="text" name="username" required />      <label>Date of Birth</label>      <input type="date" name="birthdate" required />      <button type="submit">Next</button>      <div class="back-button-container">        <a href="login.php" class="back-button">Back to Login</a>      </div>    </form>  </div></body></html>